SS.terms = {
  "token": {"zh": "词元", "en": "Token", "alias": ["tokens"], "d": ["语言模型读写的离散单位，可对应整词、子词、标点或一段字节。", "A discrete unit read or written by a language model, which can represent a word, a subword, punctuation, or a sequence of bytes."], "see": "tok", "tag": "generic"},
  "tokenizer": {"zh": "分词器", "en": "Tokenizer", "alias": ["tokenizers", "tokeniser"], "d": ["按词表和切分规则在文本与词元序列之间转换的组件。", "A component that converts between text and token sequences according to a vocabulary and segmentation rules."], "see": "tok", "tag": "generic"},
  "vocabulary": {"zh": "词表", "en": "Vocabulary", "alias": ["token vocabulary"], "d": ["分词器维护的可用词元及其整数编号的对应关系。", "The mapping maintained by a tokenizer between available tokens and their integer identifiers."], "see": "tok", "tag": "generic"},
  "logits": {"zh": "未归一化分数", "en": "Logits", "alias": ["logit"], "d": ["模型为候选输出计算的原始分数，可通过 softmax 转换为概率分布。", "Raw scores computed by a model for candidate outputs. A softmax can convert them into a probability distribution."], "see": "tok", "tag": "generic"},
  "autoregressive-generation": {"zh": "自回归生成", "en": "Autoregressive Generation", "alias": ["自回归", "autoregressive"], "d": ["依据已有序列逐步预测下一项，并将生成结果加入序列以参与下一步预测。", "Predicts the next item from the existing sequence and adds it to the sequence for use in the following prediction."], "see": "tok", "tag": "generic"},
  "causal-mask": {"zh": "因果掩码", "en": "Causal Mask", "alias": ["causal masking"], "d": ["在自回归注意力中屏蔽当前位置之后的输入，使当前表示只能使用本位置及更早位置的信息。", "Blocks access to later positions in autoregressive attention so the current representation only uses its own position and earlier ones."], "see": "attn", "tag": "generic"},
  "attention-head": {"zh": "注意力头", "en": "Attention Head", "alias": ["attention heads"], "d": ["注意力层中独立计算一组注意力权重及输出的计算通道。", "A channel in an attention layer that independently computes its own attention weights and output."], "see": "attn", "tag": "generic"},
  "gqa": {"zh": "分组查询注意力", "en": "GQA", "alias": ["Grouped-query attention", "Grouped query attention"], "d": ["让一组查询头共享同一个键头和值头的注意力设计，可减少需要保存的键和值。", "An attention design in which a group of query heads shares a key head and a value head, reducing the keys and values that must be stored."], "see": "attn", "tag": "generic"},
  "ffn": {"zh": "前馈网络", "en": "Feed-forward Network", "alias": ["feedforward network", "feed-forward networks", "FFN"], "d": ["Transformer 块中的可学习变换，通常对序列中各位置的表示独立执行。", "A learned transformation in a Transformer block, typically applied independently to the representation at each sequence position."], "see": "march", "tag": "generic"},
  "moe": {"zh": "混合专家", "en": "MoE", "alias": ["Mixture of Experts", "mixture-of-experts", "混合专家模型"], "d": ["将多个专家子模块组合在一起、由路由器选择部分专家处理各输入的模型设计。", "A model design that combines multiple expert modules and uses a router to select a subset to process each input."], "see": "march", "tag": "generic"},
  "expert-parallelism": {"zh": "专家并行", "en": "Expert Parallelism", "alias": [], "d": ["把混合专家层的专家分布到多台设备，并把输入发送给负责计算已选专家的设备。", "Places experts of a mixture-of-experts layer on multiple devices and dispatches inputs to the devices that compute the selected experts."], "see": "march", "tag": "generic"},
  "bf16": {"zh": "BF16 浮点格式", "en": "BF16", "alias": ["Bfloat16"], "d": ["一种 16 位浮点格式，指数域宽度与 FP32 相同，有效位数较少。", "A 16-bit floating-point format with the same exponent width as FP32 and fewer significant bits."], "see": "msize", "tag": "generic"},
  "ptq": {"zh": "训练后量化", "en": "PTQ", "alias": ["Post-training quantization", "Post-training quantisation"], "d": ["在模型训练完成后，将已有模型中的数值转换为较低精度表示。某些方法使用样本校准量化参数。", "Converts values in an already trained model to a lower-precision representation. Some methods use samples to calibrate the quantization parameters."], "see": "quant", "tag": "generic"},
  "qat": {"zh": "量化感知训练", "en": "QAT", "alias": ["Quantization-aware training", "Quantisation-aware training"], "d": ["训练时模拟量化带来的舍入和截断，使模型参数能够适应部署时的低精度表示。", "Simulates quantization effects such as rounding and clipping during training so the model parameters can adapt to the lower-precision deployment representation."], "see": "quant", "tag": "generic"},
  "pretraining": {"zh": "预训练", "en": "Pretraining", "alias": ["pre-training"], "d": ["在后续任务适配之前，使用较大规模的数据训练模型初始参数的阶段。", "The stage in which initial model parameters are learned from a large dataset before any downstream adaptation."], "see": "ft", "tag": "generic"},
  "sft": {"zh": "监督微调", "en": "Supervised Fine-Tuning", "alias": ["SFT", "supervised finetuning"], "d": ["使用带有目标输出的示例继续训练已有模型，使其适应特定任务或响应规范。", "Continues training an existing model on examples with target outputs to adapt it to a task or response format."], "see": "ft", "tag": "generic"},
  "dpo": {"zh": "直接偏好优化", "en": "DPO", "alias": ["Direct Preference Optimization"], "d": ["使用对同一输入的偏好与非偏好响应成对训练模型，基于参考模型调整两种响应的相对概率。", "Trains on paired preferred and rejected responses to the same input, adjusting their relative probabilities against a reference model."], "see": "ft", "tag": "generic"},
  "lora": {"zh": "低秩适配", "en": "LoRA", "alias": ["Low-Rank Adaptation"], "d": ["冻结模型原有权重，用低秩矩阵的乘积表示并训练选定权重的增量。", "Freezes the original model weights and trains updates to selected weights as products of low-rank matrices."], "see": "ft", "tag": "generic"},
  "prefill": {"zh": "预填充", "en": "Prefill", "alias": ["预填充阶段"], "d": ["自回归 Transformer 处理输入序列并建立初始注意力键值缓存的阶段。", "The phase in which an autoregressive Transformer processes the input sequence and builds its initial attention key/value cache."], "see": "pd", "tag": "generic"},
  "decode": {"zh": "解码", "en": "Decode", "alias": ["解码阶段", "decoding phase"], "d": ["从编码表示还原或生成内容的过程。在自回归推理中，模型利用已有上下文逐步生成输出 token。", "The process of recovering or generating content from an encoded representation. In autoregressive inference, the model uses the existing context to generate output tokens step by step."], "see": "pd", "tag": "generic"},
  "ttft": {"zh": "首 token 时延", "en": "TTFT", "alias": ["首 token 延迟", "首字延迟", "首字时延", "首词延迟", "Time to first token"], "d": ["从发出推理请求到收到第一个输出 token 的时间。", "The elapsed time from sending an inference request to receiving the first output token."], "see": "b-goodput", "tag": "generic"},
  "itl": {"zh": "token 间时延", "en": "ITL", "alias": ["token 间延迟", "Inter-token latency"], "d": ["相邻两个输出 token 到达之间的时间间隔，常以多个间隔的均值或分位数汇报。", "The time between successive output tokens, commonly reported as a mean or percentile across gaps."], "see": "b-goodput", "tag": "generic"},
  "continuous-batching": {"zh": "连续批处理", "en": "Continuous Batching", "alias": [], "d": ["推理调度方式，在生成迭代之间更新批次成员，使已完成的请求退出并让排队的请求加入。", "An inference scheduling method that updates batch membership between generation iterations, removing completed requests and admitting queued requests."], "see": "infer", "tag": "generic"},
  "prefix-caching": {"zh": "前缀缓存", "en": "Prefix Caching", "alias": ["prefix cache"], "d": ["保存输入前缀的注意力键值，使后续具有相同前缀的请求能够重用这部分计算结果。", "Stores attention keys and values for an input prefix so later requests with the same prefix can reuse that computation."], "see": "f-sglang", "tag": "generic"},
  "kv-aware-routing": {"zh": "KV 感知路由", "en": "KV-aware Routing", "alias": [], "d": ["推理请求的路由方式，在选择工作进程时将可复用的键值缓存纳入考虑。", "An inference routing method that considers reusable key/value cache entries when selecting a worker."], "see": "f-route", "tag": "generic"},
  "context-length": {"zh": "上下文长度", "en": "Context Length", "alias": [], "d": ["模型处理某个位置时可以参照的上下文所包含的 token 数量。", "The number of tokens in the context available to a model when it processes a position."], "see": "kv", "tag": "generic"},
  "model-weights": {"zh": "模型权重", "en": "Model Weights", "alias": ["权重"], "d": ["模型通过训练学习的数值参数，用于确定模型在前向计算中如何转换输入。", "Numerical parameters learned during training that determine how a model transforms its inputs during a forward pass."], "see": "msize", "tag": "generic"},
  "embedding": {"zh": "嵌入向量", "en": "Embedding", "alias": ["嵌入", "嵌入表示", "embeddings"], "d": ["将文本、图像等输入映射到向量空间得到的数值表示，可用于比较输入之间的相似性。", "A numeric representation produced by mapping an input such as text or an image into a vector space, where inputs can be compared for similarity."], "see": "embed", "tag": "generic"},
  "text-chunk": {"zh": "文本块", "en": "Text Chunk", "alias": ["文档片段", "text chunks", "document chunk"], "d": ["从原文划分出的独立片段，可分别编码、建立索引并参与检索。", "A passage split from a source document that can be encoded, indexed, and retrieved independently."], "see": "embed", "tag": "generic"},
  "similarity": {"zh": "相似度", "en": "Similarity", "alias": ["语义相似度", "semantic similarity", "similarity score", "similarity scoring"], "d": ["衡量两个对象接近程度的数值。向量检索可通过嵌入向量的相似度估计内容在语义上的接近程度。", "A value that measures how close two objects are. Vector search can estimate the semantic similarity of content from the similarity of its embeddings."], "see": "vec", "tag": "generic"},
  "hnsw": {"zh": "HNSW", "en": "HNSW", "alias": ["分层可导航小世界图", "Hierarchical Navigable Small World", "Hierarchical Navigable Small World graph"], "d": ["用于近似最近邻检索的多层图索引，查询从上层图定位大致区域，再在下层细化候选。", "A multilayer graph index for approximate nearest-neighbor search. A query navigates upper layers to locate a region and lower layers to refine the candidates."], "see": "vec", "tag": "generic"},
  "nearest-neighbor": {"zh": "最近邻检索", "en": "Nearest-neighbor Search", "alias": ["最近邻查询", "nearest neighbor search"], "d": ["按指定距离或相似度度量查找与查询向量最接近的向量。", "Retrieves vectors closest to a query vector under a specified distance or similarity measure."], "see": "vec", "tag": "generic"},
  "reranking": {"zh": "重排", "en": "Reranking", "alias": ["重新排序", "rerank", "re-ranking"], "d": ["对初步检索的候选重新评分并排序，通常使用能联合评估查询与候选内容的模型。", "Rescores and reorders the candidates from an initial retrieval pass, often using a model that evaluates a query and candidate content together."], "see": "rag", "tag": "generic"},
  "tool-call": {"zh": "工具调用", "en": "Tool Call", "alias": ["工具调用请求", "tool calls", "tool calling"], "d": ["由模型生成、由应用执行的结构化请求，通常指定外部工具名称和调用参数。", "A structured request generated by a model and executed by the application, typically specifying an external tool and its arguments."], "see": "agent", "tag": "generic"},
  "domain-randomization": {"zh": "领域随机化", "en": "Domain Randomization", "alias": ["域随机化"], "d": ["训练时从指定范围抽取场景、物理或传感器参数，生成多样的仿真样本。", "Samples scene, physics, or sensor parameters from specified ranges during training to produce varied simulated examples."], "see": "simu", "tag": "generic"},
  "sim-to-real-gap": {"zh": "仿真到现实差距", "en": "Sim-to-real Gap", "alias": ["simulation-to-reality gap"], "d": ["仿真与真实环境之间的差异，可能影响在仿真中训练的模型在真实环境中的表现。", "Differences between simulated and real environments that can affect how a simulation-trained model performs in the real world."], "see": "simu", "tag": "generic"},
  "batch-processing": {"zh": "批处理", "en": "Batch Processing", "alias": ["batch job", "batch jobs"], "d": ["对边界已定的一批输入统一执行处理，适用于定期计算或对固定输入重新计算。", "Processes a bounded set of inputs as a unit, as in a scheduled computation or a rerun over a fixed input."], "see": "pipe", "tag": "generic"},
  "stream-processing": {"zh": "流处理", "en": "Stream Processing", "alias": ["streaming job", "streaming jobs"], "d": ["随事件到达增量处理持续输入的数据，按处理逻辑维护状态或更新输出。", "Processes a continuing input incrementally as events arrive, maintaining state or updating outputs according to the processing logic."], "see": "pipe", "tag": "generic"},
  "parquet": {"zh": "Parquet", "en": "Parquet", "alias": ["Apache Parquet"], "d": ["开放的列式文件格式，将一组行中同一列的值组织在一起，支持按列读取和编码压缩。", "An open columnar file format that groups values of each column within a set of rows, supporting column selection, encoding, and compression."], "see": "lake", "tag": "generic"},
  "time-travel": {"zh": "时间旅行", "en": "Time Travel", "alias": ["time-travel"], "d": ["在支持版本的表格式中，按快照、版本或时间读取表的历史状态。", "Reads a historical table state by snapshot, version, or time in a table format that supports versioning."], "see": "otf", "tag": "generic"},
  "metadata": {"zh": "元数据", "en": "Metadata", "alias": [], "d": ["用于描述、定位或管理数据的信息，例如文件名、权限、大小和存放位置。", "Information that describes, locates, or manages data, such as a file name, permissions, size, and storage location."], "see": "meta", "tag": "generic"},
  "shard": {"zh": "分片", "en": "Shard", "alias": ["shards"], "d": ["数据集、索引或模型状态的一个子集，可由不同文件、设备或进程分别存放或处理。", "A subset of a dataset, index, or model state that can be stored or processed separately by different files, devices, or processes."], "see": "ds", "tag": "generic"},
  "prefetch": {"zh": "预取", "en": "Prefetch", "alias": ["prefetching"], "d": ["在数据实际被请求或消费之前从下一层提前读取，使读取可与当前计算重叠。", "Fetches data from the next tier before it is requested or consumed so the fetch can overlap current computation."], "see": "ds", "tag": "generic"},
  "tensor": {"zh": "张量", "en": "Tensor", "alias": ["tensors"], "d": ["机器学习中用于表示输入、权重或中间结果的多维数值数组。", "A multidimensional numeric array used to represent inputs, weights, or intermediate results in machine learning."], "see": "dist", "tag": "generic"},
  "gradient": {"zh": "梯度", "en": "Gradient", "alias": ["gradients"], "d": ["损失函数对模型参数的一阶偏导数组成的向量，用来指导参数更新。", "The vector of first partial derivatives of a loss function with respect to the model parameters, used to guide parameter updates."], "see": "dist", "tag": "generic"},
  "optimizer": {"zh": "优化器", "en": "Optimizer", "alias": ["optimiser", "optimizers", "optimisers"], "d": ["使用梯度等信息更新模型参数的算法，可保存动量等跨训练步的状态。", "An algorithm that updates model parameters using information such as gradients and may keep state such as momentum across training steps."], "see": "ckpt", "tag": "generic"},
  "data-parallelism": {"zh": "数据并行", "en": "Data Parallelism", "alias": ["data parallel", "data-parallel"], "d": ["让多个模型副本处理不同的样本，并在训练中汇总各副本计算的梯度。", "Runs multiple model replicas on different samples and aggregates the gradients computed by the replicas during training."], "see": "dist", "tag": "generic"},
  "tensor-parallelism": {"zh": "张量并行", "en": "Tensor Parallelism", "alias": ["tensor parallel", "tensor-parallel"], "d": ["将单层的张量和相应计算分布到多个设备，并在需要时交换或汇总中间结果。", "Distributes tensors and the associated computation for a layer across devices, exchanging or combining intermediate results where needed."], "see": "dist", "tag": "generic"},
  "pipeline-parallelism": {"zh": "流水线并行", "en": "Pipeline Parallelism", "alias": ["pipeline parallel", "pipeline-parallel"], "d": ["将模型层划分为顺序执行的阶段，多个小批次可以同时处于不同阶段。", "Splits model layers into sequential stages so multiple microbatches can occupy different stages at the same time."], "see": "dist", "tag": "generic"},
  "microbatch": {"zh": "小批次", "en": "Microbatch", "alias": ["microbatches", "微批次", "micro-batch"], "d": ["从一个训练批次切分出的子批次，可作为流水线调度或梯度累积的执行单位。", "A subdivision of a training batch that can be scheduled through a pipeline or processed as a unit for gradient accumulation."], "see": "dist", "tag": "generic"},
  "collective": {"zh": "集合通信", "en": "Collective Communication", "alias": ["collective operation", "collectives"], "d": ["一组进程共同参与的通信操作，例如广播、汇集或归约。", "A communication operation in which a group of processes participates, such as a broadcast, gather, or reduction."], "see": "dist", "tag": "generic"},
  "all-reduce": {"zh": "全归约", "en": "All-reduce", "alias": ["AllReduce", "all reduce"], "d": ["将所有参与者的输入按求和等运算逐元素合并，并把完整结果返回给每个参与者。", "Combines the participants’ inputs element by element using an operation such as sum and returns the full result to each participant."], "see": "dist", "tag": "generic"},
  "activation": {"zh": "激活值", "en": "Activation", "alias": ["activations"], "d": ["神经网络层在处理输入后产生的值，可作为下一层输入，也可为反向传播保留。", "A value produced by a neural network layer from its input, which can feed the next layer or be retained for backpropagation."], "see": "dist", "tag": "generic"},
  "working-set": {"zh": "工作集", "en": "Working Set", "alias": [], "d": ["在给定计算阶段或时间窗口内活跃访问的数据集合。", "The set of data actively accessed during a phase of computation or a given time window."], "see": "b-params", "tag": "generic"},
  "gpu": {"zh": "图形处理器", "en": "GPU", "alias": ["Graphics processing unit"], "d": ["面向大量并行计算的处理器，常用于图形渲染和机器学习中的张量运算。", "A processor designed for highly parallel computation, commonly used for graphics rendering and tensor operations in machine learning."], "see": "gpu", "tag": "generic"},
  "hbm": {"zh": "高带宽内存", "en": "HBM", "alias": ["High Bandwidth Memory", "高带宽显存"], "d": ["将多层 DRAM 裸片堆叠起来、通过宽接口提供高内存带宽的一类标准化存储器。", "A standardized memory technology that stacks DRAM dies and uses a wide interface to provide high memory bandwidth."], "see": "gpu", "tag": "generic"},
  "dram": {"zh": "动态随机存取存储器", "en": "DRAM", "alias": ["Dynamic random-access memory", "Dynamic random access memory"], "d": ["通过存储单元电荷保存数据的易失性存储器，运行中必须定期刷新。", "Volatile memory that stores data as charge in cells and must be refreshed periodically during operation."], "see": "gpu", "tag": "generic"},
  "pcie": {"zh": "PCIe", "en": "PCIe", "alias": ["PCI Express", "Peripheral Component Interconnect Express"], "d": ["连接处理器、加速器、网卡和存储设备的高速串行互连标准，链路可以由多条通道组成。", "A high-speed serial interconnect standard for processors, accelerators, network adapters, and storage devices, with links that can use multiple lanes."], "see": "nvl", "tag": "generic"},
  "dma": {"zh": "直接内存访问", "en": "DMA", "alias": ["Direct memory access"], "d": ["由设备或 DMA 引擎在设备和内存之间搬运数据，CPU 可以发起或管理传输。", "Transfers data between a device and memory using a device or DMA engine. The CPU can initiate or manage the transfer."], "see": "gds", "tag": "generic"},
  "p2p": {"zh": "对等传输", "en": "P2P", "alias": ["peer-to-peer transfer", "peer-to-peer access"], "d": ["允许两个设备或端点彼此直接传输数据的方式。", "A transfer method that allows two devices or endpoints to move data directly between them."], "see": "nvl", "tag": "generic"},
  "nic": {"zh": "网卡", "en": "NIC", "alias": ["Network interface card", "Network interface controller", "network adapter", "network adapters"], "d": ["将主机连接到网络、负责收发报文的硬件接口。", "A hardware interface that connects a host to a network and sends and receives packets."], "see": "rdma", "tag": "generic"},
  "dpu": {"zh": "数据处理器", "en": "DPU", "alias": ["Data processing unit"], "d": ["面向基础设施数据路径的可编程处理器，可承担网络、存储和安全处理等卸载任务。", "A programmable processor for infrastructure data paths that can offload functions such as networking, storage, and security processing."], "see": "n-bf", "tag": "generic"},
  "numa": {"zh": "非一致性内存访问", "en": "NUMA", "alias": ["Non-uniform memory access"], "d": ["处理器访问内存的成本随内存所在节点而变化的体系结构，通常访问本地内存的延迟更低。", "An architecture in which memory access cost depends on the node that holds the memory, with local memory accesses typically having lower latency."], "see": "n-grace", "tag": "generic"},
  "hca": {"zh": "主机通道适配器", "en": "HCA", "alias": ["Host channel adapter", "主机通道适配卡"], "d": ["将主机接入 InfiniBand 结构的适配器，为应用提供消息传输和远程直接内存访问能力。", "An adapter that connects a host to an InfiniBand fabric and provides messaging and remote direct memory access."], "see": "ib", "tag": "generic"},
  "lid": {"zh": "本地标识符", "en": "LID", "alias": ["Local identifier"], "d": ["由子网管理器分配给 InfiniBand 端口的子网内地址，交换机据此转发单播报文。", "A subnet-local address assigned to an InfiniBand port by the subnet manager and used by switches to forward unicast packets."], "see": "ib", "tag": "generic"},
  "subnet-manager": {"zh": "子网管理器", "en": "Subnet Manager", "alias": ["SM"], "d": ["发现并配置 InfiniBand 子网的管理组件，负责分配端口地址和配置转发表。", "The management component that discovers and configures an InfiniBand subnet, assigns port addresses, and programs forwarding tables."], "see": "ib", "tag": "generic"},
  "virtual-lane": {"zh": "虚拟通道", "en": "Virtual Lane", "alias": ["virtual lanes", "VL", "VLs"], "d": ["在同一条 InfiniBand 物理链路上复用的逻辑流量通道。承载数据的各通道可独立实施链路级流量控制。", "A logical traffic lane multiplexed over an InfiniBand physical link. Data lanes can apply link-level flow control independently."], "see": "ib", "tag": "generic"},
  "link-credit": {"zh": "链路信用", "en": "Link Credit", "alias": ["信用", "credit", "credits"], "d": ["链路接收端通告的缓冲额度，发送端用它判断当前是否可以发送报文。", "Receive buffer space advertised by a link receiver and used by the sender to determine whether it can transmit a packet."], "see": "ib", "tag": "generic"},
  "backpressure": {"zh": "背压", "en": "Backpressure", "alias": ["back pressure", "反压"], "d": ["下游服务能力不足时减少接收，由流控将等待或降速传递给上游的现象。", "Occurs when a downstream component reduces intake and flow control propagates waiting or rate reduction upstream."], "see": "ib", "tag": "generic"},
  "reliable-connected": {"zh": "可靠连接", "en": "Reliable Connected Transport", "alias": ["RC", "Reliable Connection"], "d": ["RDMA 传输服务类型，在一对已连接的队列对之间提供有序、可靠的消息传递。", "An RDMA transport service that provides ordered, reliable message delivery between two connected queue pairs."], "see": "roce", "tag": "generic"},
  "pfc": {"zh": "PFC", "en": "PFC", "alias": ["基于优先级的流量控制", "基于优先级的流控", "优先级流控", "Priority-based Flow Control", "Priority Flow Control"], "d": ["基于优先级的流量控制是一种以太网链路级流控机制，允许接收端请求相邻发送端暂停指定优先级的流量。", "Priority-based Flow Control is an Ethernet link-level mechanism that lets a receiver ask its directly connected sender to pause traffic at selected priorities."], "see": "cong", "tag": "generic"},
  "ecn": {"zh": "ECN", "en": "ECN", "alias": ["显式拥塞通知", "Explicit Congestion Notification"], "d": ["显式拥塞通知在支持 ECN 的 IP 报文上标记拥塞，使端点能根据拥塞反馈调整发送。", "Explicit Congestion Notification signals congestion by marking ECN-capable IP packets so endpoints can adjust transmission in response to feedback."], "see": "cong", "tag": "generic"},
  "cnp": {"zh": "CNP", "en": "CNP", "alias": ["拥塞通知报文", "拥塞通知包", "Congestion Notification Packet"], "d": ["拥塞通知报文由 RoCE 接收端发回发送端，用于触发相应流的发送速率调整。", "A Congestion Notification Packet is sent from a RoCE receiver to a sender to trigger a rate adjustment for the affected flow."], "see": "cong", "tag": "generic"},
  "dcqcn": {"zh": "DCQCN", "en": "DCQCN", "alias": ["Data Center Quantized Congestion Notification"], "d": ["面向 RoCEv2 的端到端拥塞控制算法，使用 ECN 标记和接收端反馈来调节发送速率。", "An end-to-end congestion-control algorithm for RoCEv2 that uses ECN marks and receiver feedback to regulate the sending rate."], "see": "cong", "tag": "generic"},
  "dscp": {"zh": "差分服务代码点", "en": "DSCP", "alias": ["Differentiated Services Code Point", "区分服务代码点"], "d": ["IP 首部中的分类字段，网络设备可根据其值选择队列、调度或丢弃处理。", "A classification field in the IP header that devices can use to select queuing, scheduling, or drop behavior."], "see": "v-ncp", "tag": "generic"},
  "ecmp": {"zh": "等价多路径", "en": "ECMP", "alias": ["Equal-cost multipath", "Equal-cost multi-path"], "d": ["目的地有多条代价相同的路径时，设备可将不同流分配到不同下一跳。", "When several paths to a destination have equal cost, a device can distribute flows across the available next hops."], "see": "topo", "tag": "generic"},
  "fat-tree": {"zh": "胖树", "en": "Fat-tree", "alias": ["fat tree"], "d": ["一种分层交换拓扑，在不同层级之间布置多条并行路径以承载跨分支流量。", "A hierarchical switching topology that uses multiple parallel paths between layers to carry traffic between branches."], "see": "topo", "tag": "generic"},
  "oversubscription": {"zh": "超卖比", "en": "Oversubscription", "alias": ["收敛比", "oversubscription ratio", "超额订阅"], "d": ["交换网络中面向服务器的总链路带宽与可用上行带宽的比例。", "The ratio of aggregate server-facing link bandwidth to available uplink bandwidth in a switching network."], "see": "topo", "tag": "generic"},
  "queue-depth": {"zh": "队列深度", "en": "Queue Depth", "alias": [], "d": ["等待服务的项目数量或数据量，例如网络缓冲中的报文字节数或存储路径中的待处理请求数。", "The number or amount of items waiting for service, such as packet bytes queued in a network buffer or pending requests in a storage path."], "see": "b-params", "tag": "generic"},
  "tcp": {"zh": "传输控制协议", "en": "TCP", "alias": ["Transmission Control Protocol"], "d": ["面向连接的传输协议，为应用提供可靠、有序的字节流。", "A connection-oriented transport protocol that provides applications with a reliable, ordered byte stream."], "see": "nvmeof", "tag": "generic"},
  "udp": {"zh": "用户数据报协议", "en": "UDP", "alias": ["User Datagram Protocol"], "d": ["基于数据报的传输协议，提供端口寻址，交付顺序和重传由使用方按需实现。", "A datagram transport protocol that provides port addressing and leaves ordering and retransmission to its users as needed."], "see": "roce", "tag": "generic"},
  "iwarp": {"zh": "iWARP", "en": "iWARP", "alias": [], "d": ["一组通过 IP 网络实现远程直接内存访问的协议，通常利用 TCP 提供可靠传输。", "A suite of protocols for remote direct memory access over IP networks, typically using TCP for reliable transport."], "see": "rdma", "tag": "generic"},
  "rpc": {"zh": "远程过程调用", "en": "RPC", "alias": ["Remote procedure call", "RPCs"], "d": ["让客户端向另一进程或主机请求执行某个过程并接收结果的通信机制。", "A communication mechanism that lets a client request execution of a procedure on another process or host and receive the result."], "see": "v-nfsrdma", "tag": "generic"},
  "arp": {"zh": "地址解析协议", "en": "ARP", "alias": ["Address Resolution Protocol"], "d": ["在本地链路上查询 IPv4 地址对应的链路层地址的协议。", "A protocol for finding the link-layer address associated with an IPv4 address on the local link."], "see": "v-nfs", "tag": "generic"},
  "vip": {"zh": "虚拟 IP", "en": "Virtual IP", "alias": ["VIP", "VIPs", "virtual IP address", "虚拟 IP 地址", "虚拟 IP（VIP）"], "d": ["由服务或逻辑接口持有的 IP 地址，可配合故障切换或负载分布在不同节点上提供访问。", "An IP address associated with a service or logical interface that can be served by different nodes for failover or load distribution."], "see": "v-nfs", "tag": "generic"},
  "vlan": {"zh": "虚拟局域网", "en": "VLAN", "alias": ["Virtual LAN", "Virtual local area network", "VLANs"], "d": ["在共享二层网络设施上划分的逻辑广播域。", "A logical broadcast domain established on shared Layer 2 network infrastructure."], "see": "v-rack", "tag": "generic"},
  "vxlan": {"zh": "VXLAN", "en": "VXLAN", "alias": ["Virtual Extensible LAN"], "d": ["将以太网帧封装在 UDP/IP 中，使二层逻辑网络可跨越三层基础网络的技术。", "Encapsulates Ethernet frames in UDP/IP so a logical Layer 2 network can span a Layer 3 underlay."], "see": "v-ncp", "tag": "generic"},
  "vrf": {"zh": "虚拟路由与转发", "en": "VRF", "alias": ["Virtual routing and forwarding"], "d": ["在同一台设备上维护彼此独立的路由和转发表的机制。", "A mechanism for maintaining independent routing and forwarding tables on the same device."], "see": "v-ncp", "tag": "generic"},
  "mlag": {"zh": "多机箱链路聚合", "en": "MLAG", "alias": ["Multi-chassis link aggregation"], "d": ["将连接到不同交换机的链路组成一个逻辑聚合组，使接入设备可同时使用这些链路。", "Combines links to different switches into one logical aggregation group so an attached device can use the links together."], "see": "v-rack", "tag": "generic"},
  "rss": {"zh": "接收端缩放", "en": "RSS", "alias": ["Receive Side Scaling", "Receive-side scaling"], "d": ["在接收端根据报文字段分散流量到多个接收队列，使多个 CPU 核可并行处理。", "Distributes incoming traffic across receive queues based on packet fields so multiple CPU cores can process it in parallel."], "see": "v-smb", "tag": "generic"},
  "mtls": {"zh": "双向 TLS", "en": "Mutual TLS", "alias": ["mTLS", "双向认证 TLS"], "d": ["TLS 客户端和服务端都出示证书并验证对方身份的认证方式。", "A TLS authentication mode in which both the client and server present certificates and verify the peer’s identity."], "see": "v-repl", "tag": "generic"},
  "nlm": {"zh": "网络锁管理器", "en": "NLM", "alias": ["Network Lock Manager"], "d": ["与 NFSv2、NFSv3 配合使用的文件锁协议，支持对文件或字节范围协调锁定。", "A file-locking protocol used with NFSv2 and NFSv3 to coordinate locks on files or byte ranges."], "see": "v-nfs", "tag": "generic"},
  "spn": {"zh": "服务主体名称", "en": "SPN", "alias": ["Service principal name"], "d": ["Kerberos 用于标识服务实例的名称，客户端根据该名称申请访问相应服务的票据。", "A Kerberos name that identifies a service instance. Clients use it to request a ticket for that service."], "see": "v-smb", "tag": "generic"},
  "kerberos": {"zh": "Kerberos", "en": "Kerberos", "alias": [], "d": ["使用由可信密钥分发中心颁发的票据，对客户端和服务进行身份验证的网络协议。", "A network authentication protocol that uses tickets issued by a trusted key distribution center to authenticate clients and services."], "see": "v-smb", "tag": "generic"},
  "ntlm": {"zh": "NTLM", "en": "NTLM", "alias": ["NTLMv2"], "d": ["Windows 使用的一族质询应答身份验证协议，可用于支持该验证方式的文件共享环境。", "A family of challenge-response authentication protocols used by Windows, including in file-sharing environments that support it."], "see": "v-smb", "tag": "generic"},
  "acl": {"zh": "访问控制列表", "en": "ACL", "alias": ["Access control list", "access control lists", "ACLs"], "d": ["附加于资源的一组访问规则，用于指定哪些主体拥有或被拒绝哪些权限。", "A set of rules associated with a resource that specifies which permissions are granted or denied to which principals."], "see": "v-nfs", "tag": "generic"},
  "posix": {"zh": "POSIX", "en": "POSIX", "alias": ["Portable Operating System Interface"], "d": ["定义操作系统接口的一族标准，包括文件访问接口、路径规则和权限等行为。", "A family of operating system interface standards that specifies behavior such as file access interfaces, pathname rules, and permissions."], "see": "pfs", "tag": "generic"},
  "scm": {"zh": "存储级内存", "en": "SCM", "alias": ["Storage Class Memory", "storage-class memory"], "d": ["介于主存和常规存储之间的一类低延迟非易失性介质，可为写缓冲等层级提供持久性。", "A class of low-latency nonvolatile media between main memory and conventional storage, used to provide persistence for tiers such as a write buffer."], "see": "v-scm", "tag": "generic"},
  "nvram": {"zh": "非易失性随机存取存储器", "en": "NVRAM", "alias": ["nonvolatile random-access memory", "non-volatile random access memory", "非易失性内存"], "d": ["断电后仍能保留内容的随机访问存储器，可用于持久化写缓冲或关键状态。", "Random-access memory that retains its contents without power and can be used for persistent write buffering or critical state."], "see": "v-scm", "tag": "generic"},
  "nand": {"zh": "NAND 闪存", "en": "NAND Flash", "alias": ["NAND"], "d": ["通过单元电荷保存数据的非易失性闪存，通常按页编程、按块擦除。", "Nonvolatile flash memory that stores data using charge in cells and is typically programmed by page and erased by block."], "see": "nvme", "tag": "generic"},
  "slc": {"zh": "单比特单元", "en": "SLC", "alias": ["SLC 闪存", "Single-level cell"], "d": ["每个存储单元记录一位数据的 NAND 闪存，使用两个可区分的单元状态。", "NAND flash that stores one bit per cell using two distinguishable cell states."], "see": "v-qlc", "tag": "generic"},
  "qlc": {"zh": "四比特单元", "en": "QLC", "alias": ["Quad-level cell", "四层单元"], "d": ["每个存储单元记录四位数据的 NAND 闪存组织方式，使用十六个可区分的单元状态。", "A NAND flash organization that stores four bits per cell using sixteen distinguishable cell states."], "see": "v-qlc", "tag": "generic"},
  "program-erase-cycle": {"zh": "编程／擦除周期", "en": "Program/erase Cycle", "alias": ["擦写周期", "擦写次数", "P/E cycle", "program/erase cycles"], "d": ["闪存经历编程和擦除的一轮操作。可承受的循环次数是衡量介质耐写性的指标。", "One round of flash programming and erasure. The number of cycles the medium can withstand is a measure of endurance."], "see": "v-qlc", "tag": "generic"},
  "erase-block": {"zh": "擦除块", "en": "Erase Block", "alias": ["erase blocks", "闪存擦除块"], "d": ["NAND 闪存能够一次擦除的单元，由多个可分别读取和编程的页组成。", "The unit that NAND flash can erase in a single operation, comprising pages that can be read and programmed separately."], "see": "v-qlc", "tag": "generic"},
  "write-amplification": {"zh": "写放大", "en": "Write Amplification", "alias": ["WAF", "write amplification factor", "写放大系数"], "d": ["由数据搬移、垃圾回收等引起的额外写入，通常以物理写入量与逻辑写入量的比值计量。", "Extra writes caused by work such as data relocation and garbage collection, usually measured as the ratio of physical to logical bytes written."], "see": "v-qlc", "tag": "generic"},
  "garbage-collection": {"zh": "垃圾回收", "en": "Garbage Collection", "alias": ["垃圾收集"], "d": ["在存储系统中回收失效或不再被引用的数据占用的空间，可能涉及搬移仍然有效的数据。", "In storage systems, reclaims space occupied by invalid or unreferenced data, potentially relocating still-valid data."], "see": "v-qlc", "tag": "generic"},
  "dwpd": {"zh": "每日全盘写入次数", "en": "DWPD", "alias": ["Drive writes per day", "每日盘写次数"], "d": ["在额定期限内，SSD 每天允许写入相当于其可用容量的次数。", "The number of times an SSD’s usable capacity can be written per day over its rated period."], "see": "v-qlc", "tag": "generic"},
  "tbw": {"zh": "累计写入太字节数", "en": "TBW", "alias": ["Terabytes written", "总写入量"], "d": ["以太字节表示的累计写入量，常用作 SSD 的额定耐写指标。", "Cumulative writes expressed in terabytes, commonly used as a rated endurance measure for SSDs."], "see": "v-qlc", "tag": "generic"},
  "iops": {"zh": "每秒输入输出操作数", "en": "IOPS", "alias": ["I/O operations per second", "每秒 I/O 次数"], "d": ["每秒完成的输入输出操作数量，解读结果时需结合请求大小和读写模式。", "The number of completed input/output operations per second, interpreted together with request size and read/write pattern."], "see": "b-metrics", "tag": "generic"},
  "latency": {"zh": "时延", "en": "Latency", "alias": ["延迟"], "d": ["从一次操作开始到观察到对应结果的时间。存储和网络测量通常区分测量起止点。", "Elapsed time between the start of an operation and observation of its result. Storage and network measurements ordinarily specify the measurement endpoints."], "see": "b-metrics", "tag": "generic"},
  "nvme-namespace": {"zh": "NVMe 命名空间", "en": "NVMe Namespace", "alias": ["NVMe namespaces", "命名空间（namespace）"], "d": ["通过 NVMe 控制器向主机呈现、由命名空间标识符区分的一组存储资源，例如一组逻辑块。", "A set of storage resources, such as logical blocks, presented to a host through an NVMe controller and distinguished by a namespace identifier."], "see": "nvme", "tag": "generic"},
  "nqn": {"zh": "NVMe 限定名称", "en": "NQN", "alias": ["NVMe Qualified Name", "NVMe 合格名称"], "d": ["用来在 NVMe 系统中唯一标识主机或 NVM 子系统的命名字符串。", "A naming string used to uniquely identify a host or an NVM subsystem in an NVMe system."], "see": "v-block", "tag": "generic"},
  "submission-queue": {"zh": "提交队列", "en": "Submission Queue", "alias": ["submission queues"], "d": ["NVMe 主机向控制器提交命令的队列。", "An NVMe queue through which the host submits commands to the controller."], "see": "nvme", "tag": "generic"},
  "completion-queue": {"zh": "完成队列", "en": "Completion Queue", "alias": ["completion queues"], "d": ["NVMe 控制器向主机写入命令完成状态的队列。", "An NVMe queue in which the controller posts command completion status for the host."], "see": "nvme", "tag": "generic"},
  "nvme-tcp": {"zh": "NVMe/TCP", "en": "NVMe/TCP", "alias": ["NVMe over TCP"], "d": ["在 TCP 连接上承载 NVMe 命令、响应和数据的 NVMe over Fabrics 传输。", "An NVMe over Fabrics transport that carries NVMe commands, responses, and data over TCP connections."], "see": "nvmeof", "tag": "generic"},
  "jbof": {"zh": "闪存盘柜", "en": "JBOF", "alias": ["Just a Bunch of Flash", "Just a Bunch of Flash drives", "JBoFs"], "d": ["容纳多块闪存驱动器、将其通过指定互连提供给外部主机的存储机箱。", "A storage enclosure that houses multiple flash drives and makes them available to external hosts over a specified interconnect."], "see": "v-dbox", "tag": "generic"},
  "raid": {"zh": "RAID", "en": "RAID", "alias": ["独立磁盘冗余阵列", "Redundant Array of Independent Disks"], "d": ["将多个驱动器组合起来使用的一族技术。不同级别使用不同的条带、镜像或校验布局。", "A family of techniques for using multiple drives together. RAID levels use different layouts for striping, mirroring, or parity."], "see": "ec", "tag": "generic"},
  "stripe": {"zh": "条带", "en": "Stripe", "alias": ["stripes", "RAID stripe"], "d": ["一起分布在多个存储成员上的一组数据段，带校验的布局还包含对应的校验段。", "A group of data segments placed together across multiple storage members. A parity-protected layout also includes the corresponding parity segments."], "see": "ec", "tag": "generic"},
  "stripe-count": {"zh": "条带数", "en": "Stripe Count", "alias": ["条带数量"], "d": ["在 Lustre 文件布局中，指定某个布局组件将文件数据跨多少个对象存储目标分布。", "In a Lustre file layout, specifies how many object storage targets a layout component spreads file data across."], "see": "d-stripe", "tag": "generic"},
  "stripe-size": {"zh": "条带大小", "en": "Stripe Size", "alias": ["stripe chunk size", "条带块大小", "条带尺寸"], "d": ["在 Lustre 文件布局中，连续写入一个对象存储目标后再切换至下一目标的数据长度。", "In a Lustre file layout, the contiguous amount of data placed on one object storage target before placement moves to the next."], "see": "d-stripe", "tag": "generic"},
  "parity": {"zh": "校验块", "en": "Parity", "alias": ["校验段", "校验片", "校验数据", "parity block", "parity blocks", "parity segment", "parity segments"], "d": ["由一组数据块计算出的冗余信息，数据块丢失时可与幸存块一起用于恢复。", "Redundant information computed from a set of data blocks, used with surviving blocks to reconstruct lost data."], "see": "ec", "tag": "generic"},
  "fault-domain": {"zh": "故障域", "en": "Failure Domain", "alias": ["fault domain", "failure domains"], "d": ["可能因同一个故障同时不可用的一组资源，例如同一机箱或机架内的设备。", "A group of resources that a single failure could make unavailable together, such as devices in one enclosure or rack."], "see": "v-wec", "tag": "generic"},
  "hot-spare": {"zh": "热备盘", "en": "Hot Spare", "alias": ["hot spare drive", "hot-spare drive", "hot spares", "hot-spare drives"], "d": ["预先安装并可自动接替故障驱动器、接收重建数据的备用盘。", "A preinstalled spare drive that can automatically take over for a failed drive and receive reconstructed data."], "see": "d-dcr", "tag": "generic"},
  "rebuild": {"zh": "重建", "en": "Rebuild", "alias": ["rebuilding", "rebuilds"], "d": ["成员失效后，利用幸存的数据副本或编码块恢复丢失内容、恢复冗余的过程。", "The process of reconstructing lost contents from surviving replicas or coded blocks after a member fails, restoring redundancy."], "see": "ec", "tag": "generic"},
  "degraded-mode": {"zh": "降级状态", "en": "Degraded Mode", "alias": ["degraded state", "降级运行"], "d": ["存储组失去部分冗余但仍可处理请求的状态，读取失效成员上的数据时可能需要重构。", "A storage group state in which requests can still be served with reduced redundancy. Reads of data on a failed member may require reconstruction."], "see": "d-dcr", "tag": "generic"},
  "reed-solomon": {"zh": "里德–所罗门码", "en": "Reed-Solomon Code", "alias": ["Reed-Solomon", "Reed–Solomon", "RS 码"], "d": ["一种在有限域上运算的纠错码，可通过存放附加编码符号恢复一定数量的丢失符号。", "An error-correcting code that operates over a finite field and uses additional coded symbols to recover a bounded number of missing symbols."], "see": "v-wec", "tag": "generic"},
  "mirroring": {"zh": "镜像", "en": "Mirroring", "alias": ["盘镜像", "镜像副本", "mirrored copy"], "d": ["在独立存储成员或位置保存多份相同数据，以便其中一份不可用时仍可读取。", "Stores identical copies of data on separate storage members or locations so the data remains readable if a copy becomes unavailable."], "see": "v-scm", "tag": "generic"},
  "rpo": {"zh": "恢复点目标", "en": "RPO", "alias": ["Recovery point objective"], "d": ["中断发生后，业务要求将数据恢复到的时间点目标，通常以可接受的数据丢失时间窗口表示。", "The target point in time to which data must be restored following a disruption, typically expressed as an acceptable window of data loss."], "see": "v-repl", "tag": "generic"},
  "async-replication": {"zh": "异步复制", "en": "Asynchronous Replication", "alias": ["async replication"], "d": ["源端可在远端副本完成更新前确认写入，改动按复制策略随后传输。", "The source can acknowledge a write before the remote copy is updated. Changes are sent later under the replication policy."], "see": "v-repl", "tag": "generic"},
  "sync-replication": {"zh": "同步复制", "en": "Synchronous Replication", "alias": ["sync replication"], "d": ["源端在收到复制策略所要求的同步副本确认后，才向客户端确认写入。", "The source acknowledges a write to the client after obtaining the synchronous replica confirmations required by the replication policy."], "see": "v-repl", "tag": "generic"},
  "failover": {"zh": "故障切换", "en": "Failover", "alias": ["容灾切换"], "d": ["当前服务路径、节点或站点无法服务时，将业务切换到可用的备用资源。", "Moves service to an available standby resource when the current path, node, or site cannot serve requests."], "see": "v-repl", "tag": "generic"},
  "object-key": {"zh": "对象键", "en": "Object Key", "alias": ["object keys", "对象名"], "d": ["在一个对象存储桶内标识对象的字符串，可由应用使用共同前缀组织多个对象。", "A string that identifies an object within a storage bucket. Applications can use common prefixes to organize objects."], "see": "obj", "tag": "generic"},
  "bucket": {"zh": "存储桶", "en": "Bucket", "alias": ["buckets", "对象桶"], "d": ["对象存储中用于容纳对象的逻辑容器，通常还作为配置访问策略的范围。", "A logical container for objects in an object store, commonly also serving as a scope for access policies."], "see": "obj", "tag": "generic"},
  "multipart-upload": {"zh": "分段上传", "en": "Multipart Upload", "alias": ["多段上传", "分片上传"], "d": ["先独立上传对象的各个分段，再提交分段清单，由对象存储服务组装成一个对象。", "Uploads parts of an object independently and then submits their manifest for the object storage service to assemble into one object."], "see": "obj", "tag": "generic"},
  "lustre": {"zh": "Lustre", "en": "Lustre", "alias": [], "d": ["开放源代码的并行文件系统，将元数据服务与文件内容服务分开，客户端可并行访问多个数据目标。", "An open-source parallel file system that separates metadata service from file-content service and lets clients access multiple data targets in parallel."], "see": "d-exa", "tag": "generic"},
  "mds": {"zh": "Lustre 元数据服务器", "en": "MDS", "alias": ["Lustre Metadata Server", "Lustre Metadata Servers"], "d": ["在 Lustre 中托管元数据目标，处理名称查找、属性查询和文件布局等请求的服务器。", "In Lustre, a server that hosts metadata targets and handles requests such as name lookups, attribute queries, and file layouts."], "see": "d-mds", "tag": "generic"},
  "mdt": {"zh": "元数据目标", "en": "MDT", "alias": ["Metadata target", "Metadata targets", "MDTs"], "d": ["在 Lustre 中存放文件名、属性及指向数据对象的布局等文件系统元数据的存储目标。", "In Lustre, the storage target for file system metadata such as names, attributes, and layouts that refer to data objects."], "see": "d-dom", "tag": "generic"},
  "oss": {"zh": "对象存储服务器", "en": "OSS", "alias": ["Object storage server", "Object storage servers"], "d": ["在 Lustre 中托管对象存储目标并处理客户端文件内容 I/O 的服务器。", "In Lustre, a server that hosts object storage targets and handles client I/O for file contents."], "see": "d-oss", "tag": "generic"},
  "ost": {"zh": "对象存储目标", "en": "OST", "alias": ["Object storage target", "Object storage targets", "OSTs"], "d": ["在 Lustre 中存放文件数据对象的存储目标，由对象存储服务器向客户端提供访问。", "In Lustre, a storage target that holds file data objects and is made accessible to clients by an object storage server."], "see": "d-stripe", "tag": "generic"},
  "mgs": {"zh": "管理服务器", "en": "MGS", "alias": ["Lustre management server"], "d": ["在 Lustre 中向客户端和服务器提供文件系统配置，配置保存在管理目标中。", "In Lustre, provides file system configuration to clients and servers, with configuration stored on the management target."], "see": "d-exa", "tag": "generic"},
  "lnet": {"zh": "LNet", "en": "LNet", "alias": ["Lustre Networking"], "d": ["Lustre 的网络通信层，承载客户端与服务器之间的消息，并支持跨 Lustre 网络路由。", "Lustre’s networking layer, which carries messages between clients and servers and can route traffic across Lustre networks."], "see": "d-lnet", "tag": "generic"},
  "pfl": {"zh": "渐进式文件布局", "en": "PFL", "alias": ["Progressive File Layout", "渐进式条带布局"], "d": ["Lustre 的复合文件布局，可让文件中不同字节范围采用不同的条带宽度、大小或存储池。", "A Lustre composite file layout that allows different byte ranges of a file to use different stripe counts, stripe sizes, or storage pools."], "see": "d-pfl", "tag": "generic"},
  "flr": {"zh": "文件级冗余", "en": "FLR", "alias": ["File Level Redundancy", "File-level redundancy", "文件级镜像"], "d": ["Lustre 在文件层为同一文件保存多个镜像布局的能力，可将镜像放在不同存储池。", "A Lustre capability for keeping multiple mirrored layouts for the same file, with mirrors optionally placed in distinct storage pools."], "see": "d-flr", "tag": "generic"},
  "file-layout": {"zh": "文件布局", "en": "File Layout", "alias": ["file layouts"], "d": ["在 Lustre 中描述文件数据在存储目标或布局组件之间如何放置的元数据。", "In Lustre, metadata that describes placement of file data across storage targets or layout components."], "see": "d-stripe", "tag": "generic"},
  "sfa": {"zh": "SFA", "en": "SFA", "alias": ["Storage Fusion Architecture"], "d": ["DDN 的存储阵列平台系列，提供闪存或混合介质系统，可用作 EXAScaler 的后端存储。", "DDN’s storage array platform family, with flash or hybrid-media systems that can provide backend storage for EXAScaler."], "see": "d-dcr", "tag": "ddn"},
  "dnode": {"zh": "DNode", "en": "DNode", "alias": ["DNodes", "VAST Data Node"], "d": ["VAST 的数据节点，将其管理的固态盘接入集群的 NVMe over Fabrics 网络，供计算节点访问。", "A VAST data node that connects its SSDs to the cluster’s NVMe over Fabrics network for access by compute nodes."], "see": "v-dbox", "tag": "vast"},
  "vip-pool": {"zh": "VIP 池", "en": "VIP Pool", "alias": ["virtual IP pool", "VIP pools", "virtual IP pools", "虚拟 IP 池"], "d": ["VAST 中配置的一组客户端访问 IP 地址，可在全体活跃 CNode 或指定的一组 CNode 上分配。", "A configured group of client access IP addresses in VAST, distributed over all active CNodes or a selected group of CNodes."], "see": "v-nfs", "tag": "vast"},
  "element-store": {"zh": "Element Store", "en": "Element Store", "alias": ["VAST Element Store"], "d": ["VAST 将文件、对象、块卷和表组织在一个支持多协议的命名空间中的存储层。", "The VAST storage layer that organizes files, objects, block volumes, and tables in one multiprotocol namespace."], "see": "v-datastore", "tag": "vast"},
  "vast-view": {"zh": "VAST 视图", "en": "VAST View", "alias": ["导出视图", "block-only view", "file view"], "d": ["VAST 中将 Element Store 的路径通过选定协议提供给客户端的配置对象。", "A VAST configuration object that exposes an Element Store path to clients via selected protocols."], "see": "v-datastore", "tag": "vast"},
  "view-policy": {"zh": "视图策略", "en": "View Policy", "alias": ["view policies"], "d": ["VAST 中可复用的视图配置，规定客户端访问、协议行为和权限处理等规则。", "A reusable VAST view configuration for rules such as client access, protocol behavior, and permission handling."], "see": "v-mt", "tag": "vast"},
  "qos-policy": {"zh": "QoS 策略", "en": "QoS Policy", "alias": ["QoS policies", "服务质量策略"], "d": ["VAST 中用于配置存储服务质量的规则，可为关联的视图设置 IOPS 或带宽限制等目标。", "A VAST quality-of-service configuration that can set targets such as IOPS or bandwidth limits for associated views."], "see": "v-mt", "tag": "vast"},
  "vms": {"zh": "VAST 管理服务", "en": "VMS", "alias": ["VAST Management Service", "VAST Management System"], "d": ["VAST 集群的管理服务，提供 Web、命令行和 REST 管理接口，并汇集集群指标。", "The management service for a VAST cluster, providing web, command-line, and REST management interfaces and aggregating cluster metrics."], "see": "v-mgmt", "tag": "vast"},
  "protected-path": {"zh": "受保护路径", "en": "Protected Path", "alias": ["保护路径", "protected paths"], "d": ["VAST 中指定要保护的源数据路径的配置，可为其设置本地快照或远端复制目的地。", "A VAST configuration that identifies the source data path to protect and can specify a local snapshot or remote replication destination."], "see": "v-repl", "tag": "vast"},
  "protection-policy": {"zh": "保护策略", "en": "Protection Policy", "alias": ["protection policies"], "d": ["VAST 中可复用的数据保护配置，可规定快照计划、保留时间及适用时的复制对端。", "A reusable VAST data protection configuration that can specify a snapshot schedule, a retention period, and a replication peer where applicable."], "see": "v-snap", "tag": "vast"},
  "replication-stream": {"zh": "复制流", "en": "Replication Stream", "alias": ["replication streams"], "d": ["VAST 中将受保护路径关联到复制目的地的关系，用于向该目的地传送受保护的数据。", "A VAST relationship linking a protected path to a replication destination, used to transfer the protected data to that destination."], "see": "v-repl", "tag": "vast"},
  "uplink": {"zh": "VAST Uplink", "en": "VAST Uplink", "alias": [], "d": ["VAST 的远程支持服务，已注册的集群可通过加密连接发送遥测数据供支持团队查看。", "VAST’s remote support service, through which registered clusters can send telemetry over an encrypted connection for support monitoring."], "see": "v-mgmt", "tag": "vast"},
  "llm": {"zh": "大语言模型", "en": "Large Language Model", "alias": ["LLM", "LLMs", "large language models"], "d": ["用大量文本或包含文本的数据训练、用于理解或生成语言的大规模模型。", "A large model trained on extensive text or text-containing data to understand or generate language."], "see": "tok", "tag": "generic"},
  "kv-pair": {"zh": "键值对", "en": "Key–Value Pair", "alias": ["key-value pair", "key-value pairs"], "d": ["由标识符和与之关联的值组成的数据项，可用键查找对应的值。", "A data item consisting of an identifier and an associated value that can be looked up by its key."], "see": "d-kvcore", "tag": "generic"},
  "fp8": {"zh": "FP8 浮点格式", "en": "FP8", "alias": ["8-bit floating point"], "d": ["一类 8 位浮点格式。指数位和尾数位的不同分配会改变数值范围和精度。", "A family of 8-bit floating-point formats. Different allocations of exponent and significand bits change range and precision."], "see": "quant", "tag": "generic"},
  "nvfp4": {"zh": "NVFP4 浮点格式", "en": "NVFP4", "alias": ["NVFP4 format"], "d": ["NVIDIA 的 4 位浮点数据表示方式，结合块级缩放和张量级缩放来表示数值。", "NVIDIA’s 4-bit floating-point representation, which uses block-level and tensor-level scaling to represent values."], "see": "n-blackwell", "tag": "nvidia"},
  "paged-attention": {"zh": "分页注意力", "en": "PagedAttention", "alias": ["Paged Attention"], "d": ["按块存放注意力键值缓存，并通过块表把逻辑顺序映射到物理位置的注意力方法。", "An attention method that stores the key-value cache in blocks and maps logical sequence order to physical locations through a block table."], "see": "f-vllm", "tag": "generic"},
  "radixattention": {"zh": "基数树注意力", "en": "RadixAttention", "alias": [], "d": ["SGLang 用基数树组织缓存的 token 前缀并复用相应键值状态的方法。", "The SGLang method that organizes cached token prefixes in a radix tree and reuses their key-value state."], "see": "f-sglang", "tag": "generic"},
  "radix-tree": {"zh": "基数树", "en": "Radix Tree", "alias": ["radix trees", "压缩前缀树"], "d": ["将只有一个子节点的连续路径合并的前缀树，用于按键或前缀查找。", "A prefix tree that compresses consecutive single-child paths and supports lookup by key or prefix."], "see": "f-sglang", "tag": "generic"},
  "workload-concurrency": {"zh": "请求并发数", "en": "Request Concurrency", "alias": ["并发请求数"], "d": ["同一时刻尚未完成的请求数量，压测时可设置并发上限。", "The number of requests outstanding at the same time. A load test may impose a concurrency limit."], "see": "b-goodput", "tag": "generic"},
  "e2e-latency": {"zh": "端到端时延", "en": "End-to-End Latency", "alias": ["E2E latency", "端到端延迟"], "d": ["请求从发出到完整结果返回的耗时。流式推理中，测量终点是完整输出到达。", "Elapsed time from sending a request to receiving its full result. In streaming inference the endpoint is receipt of the complete output."], "see": "b-goodput", "tag": "generic"},
  "tpot": {"zh": "每输出 token 平均时延", "en": "Time Per Output Token", "alias": ["TPOT", "平均每输出 token 耗时"], "d": ["流式推理中，首个输出 token 到达后，剩余输出 token 的平均生成间隔。", "In streaming inference, the average time per remaining output token after the first output token arrives."], "see": "b-goodput", "tag": "generic"},
  "goodput": {"zh": "有效吞吐", "en": "Goodput", "alias": ["有效吞吐量"], "d": ["推理压测中，单位时间内完成并满足约定服务目标的请求数量。", "In inference benchmarking, the number of completed requests per unit time that meet the specified service objectives."], "see": "b-goodput", "tag": "generic"},
  "slo": {"zh": "服务级别目标", "en": "Service Level Objective", "alias": ["SLO", "SLOs", "服务等级目标"], "d": ["对可测量服务指标设定的目标，例如请求时延的达标阈值。", "A target for a measurable service indicator, such as a threshold for acceptable request latency."], "see": "b-goodput", "tag": "generic"},
  "tail-latency": {"zh": "尾延迟", "en": "Tail Latency", "alias": ["tail latencies", "尾部延迟", "尾时延"], "d": ["描述低频慢请求的高分位时延，常用 p95 或 p99 表示。", "High-percentile latency that characterizes infrequent slow requests, often reported as p95 or p99."], "see": "b-metrics", "tag": "generic"},
  "percentile": {"zh": "分位数", "en": "Percentile", "alias": ["percentiles", "百分位数", "p95", "p99"], "d": ["排序样本中的分布位置，表示约有指定百分比的观测值处于该值或更低。", "A position in an ordered distribution at or below which roughly the specified percentage of observations fall."], "see": "b-metrics", "tag": "generic"},
  "block-size": {"zh": "I/O 块大小", "en": "I/O Block Size", "alias": ["I/O size", "I/O 大小", "I/O 块尺寸"], "d": ["存储负载中一次 I/O 请求读写的数据量。", "The amount of data read or written by one I/O request in a storage workload."], "see": "b-params", "tag": "generic"},
  "direct-io": {"zh": "直接 I/O", "en": "Direct I/O", "alias": ["direct IO", "O_DIRECT"], "d": ["在支持的系统中绕过操作系统文件页缓存的文件 I/O 方式。", "A file I/O mode that bypasses the operating system’s file page cache on supported systems."], "see": "b-params", "tag": "generic"},
  "page-cache": {"zh": "页缓存", "en": "Page Cache", "alias": ["文件页缓存"], "d": ["操作系统在内存中保留的文件数据页，用于缓冲读写并服务后续访问。", "File data pages the operating system keeps in memory to buffer reads and writes and serve later accesses."], "see": "b-params", "tag": "generic"},
  "buffered-io": {"zh": "缓冲 I/O", "en": "Buffered I/O", "alias": ["buffered IO"], "d": ["经操作系统文件页缓存处理读写的文件 I/O 方式。", "A file I/O mode in which reads and writes pass through the operating system’s file page cache."], "see": "b-params", "tag": "generic"},
  "read-write-mix": {"zh": "读写比例", "en": "Read/Write Mix", "alias": ["read/write ratio", "读写混合比例"], "d": ["混合 I/O 负载中读操作和写操作各占的比例。", "The proportions of read and write operations in a mixed I/O workload."], "see": "b-params", "tag": "generic"},
  "qps": {"zh": "每秒查询数", "en": "Queries per Second", "alias": ["QPS"], "d": ["单位秒内处理的查询数。报告测试结果时应明确统计完成或提交的查询。", "The number of queries processed per second. A benchmark report should specify whether it counts completions or submissions."], "see": "b-vdbbench", "tag": "generic"},
  "recall-at-k": {"zh": "前 k 项召回率", "en": "Recall@k", "alias": ["recall at k", "recall at K"], "d": ["向量检索返回的前 k 项中，命中精确近邻前 k 项的比例。", "The fraction of the exact top-k nearest neighbors found in the first k vector-search results."], "see": "b-vdbbench", "tag": "generic"},
  "ann": {"zh": "近似最近邻检索", "en": "Approximate Nearest Neighbor Search", "alias": ["approximate nearest-neighbor search", "ANN search", "近似近邻检索"], "d": ["通过近似算法查找与查询向量距离较近的候选项，通常允许以部分召回率换取较低搜索开销。", "Search that uses an approximate algorithm to find candidates close to a query vector, often trading some recall for lower search cost."], "see": "vec", "tag": "generic"},
  "cagra": {"zh": "CAGRA 图索引", "en": "CAGRA", "alias": [], "d": ["NVIDIA cuVS 中面向 GPU 设计的图索引及近似最近邻搜索算法。", "A GPU-oriented graph index and approximate nearest-neighbor search algorithm in NVIDIA cuVS."], "see": "n-cuvs", "tag": "nvidia"},
  "vector-db-system": {"zh": "向量数据库系统", "en": "Vector Database System", "alias": ["vector database", "vector databases", "向量数据库"], "d": ["存储向量并按距离或相似度检索近邻的数据系统，通常可为向量建立索引。", "A data system that stores vectors and retrieves nearby items by distance or similarity, typically using a vector index."], "see": "vec", "tag": "generic"},
  "row-group": {"zh": "列式存储行组", "en": "Row Group", "alias": ["row group", "row groups"], "d": ["列式存储中按一组行划定的逻辑单位，一组内各列可分开组织和读取。", "A logical unit covering a group of rows in columnar storage, with columns organized and read separately."], "see": "v-db", "tag": "generic"},
  "nfs-protocol": {"zh": "网络文件系统协议", "en": "Network File System", "alias": ["NFS", "NFSv3", "NFSv4", "NFSv4.1"], "d": ["一组通过网络访问远端文件系统的协议，客户端可对服务端文件与目录发起操作。", "A family of protocols for accessing a remote file system over a network. Clients issue operations on files and directories hosted by a server."], "see": "v-nfs", "tag": "generic"},
  "smb-protocol": {"zh": "服务器消息块协议", "en": "Server Message Block", "alias": ["SMB", "SMB2", "SMB3", "服务器消息块"], "d": ["通过网络共享文件、目录等资源的协议，支持客户端在远程共享上执行文件操作。", "A protocol for sharing resources such as files and directories over a network. Clients can perform file operations on remote shares."], "see": "v-smb", "tag": "generic"},
  "s3-api": {"zh": "S3 对象接口", "en": "S3 API", "alias": ["S3", "AWS S3", "Amazon S3", "S3-compatible API", "S3 兼容接口"], "d": ["源自 AWS S3 的对象存储接口，通过存储桶和对象键标识资源，提供对象读写和列举等操作。", "An object-storage interface originating in AWS S3, with operations to read, write, and list objects identified by bucket and object key."], "see": "obj", "tag": "generic"},
  "storage-snapshot": {"zh": "时间点快照", "en": "Point-in-Time Snapshot", "alias": ["snapshot", "snapshots", "快照"], "d": ["数据集、文件系统或应用状态在指定时点的记录，可用于访问当时的数据或恢复状态。", "A record of a data set, file system, or application state at a point in time, used to access that version or restore state."], "see": "otf", "tag": "generic"},
  "multi-tenant-platform": {"zh": "平台多租户", "en": "Platform Multi-Tenancy", "alias": ["multi-tenancy", "多租户"], "d": ["多个租户共用平台基础设施，并各自保有身份、访问或资源边界的部署方式。", "A deployment model in which tenants share platform infrastructure while retaining separate identity, access, or resource boundaries."], "see": "f-mt", "tag": "generic"},
  "data-dedup": {"zh": "数据去重", "en": "Data Deduplication", "alias": ["deduplication", "dedup", "去重"], "d": ["识别重复的数据项并保留所需数量的副本，可应用在文件、块或数据集记录等粒度。", "Identifies duplicates and keeps the required number of copies, for units such as files, blocks, or data set records."], "see": "dr", "tag": "generic"},
  "zero-copy": {"zh": "零拷贝", "en": "Zero-Copy", "alias": ["zero copy", "零复制"], "d": ["通过减少或省去特定软件数据路径中的中间缓冲区复制来移动数据。", "Moves data while reducing or eliminating intermediate buffer copies in a specified software data path."], "see": "rdma", "tag": "generic"},
  "ssd": {"zh": "固态硬盘", "en": "Solid-State Drive", "alias": ["SSD", "SSDs", "固态盘"], "d": ["使用固态介质存储数据的设备，常见实现使用 NAND 闪存并由控制器管理。", "A storage device using solid-state media, commonly NAND flash managed by a controller."], "see": "nvme", "tag": "generic"},
  "tlc": {"zh": "三比特单元", "en": "Triple-Level Cell", "alias": ["TLC", "TLC NAND"], "d": ["每个存储单元可编码三个比特的 NAND 闪存。", "NAND flash that encodes three bits per cell."], "see": "v-qlc", "tag": "generic"},
  "sed": {"zh": "自加密驱动器", "en": "Self-Encrypting Drive", "alias": ["SED", "SEDs", "self-encrypting drives", "自加密盘"], "d": ["在驱动器内部加密写入的用户数据并解密读取数据的存储设备。", "A storage device that encrypts user data on writes and decrypts it on reads within the drive."], "see": "d-kmip", "tag": "generic"},
  "kmip": {"zh": "密钥管理互操作协议", "en": "Key Management Interoperability Protocol", "alias": ["KMIP"], "d": ["OASIS 制定的协议，规范客户端对密钥管理服务中的密钥及相关对象执行操作的接口。", "An OASIS protocol that standardizes client operations on keys and related objects in a key management service."], "see": "d-kmip", "tag": "generic"},
  "csi": {"zh": "容器存储接口", "en": "Container Storage Interface", "alias": ["CSI"], "d": ["容器编排系统与存储插件之间用于供应、挂载和管理卷的标准接口。", "A standard interface between container orchestrators and storage plugins for provisioning, mounting, and managing volumes."], "see": "d-csi", "tag": "generic"},
  "persistent-volume": {"zh": "Kubernetes 持久卷", "en": "Kubernetes Persistent Volume", "alias": ["PersistentVolume", "Kubernetes PV", "PV", "PVs"], "d": ["Kubernetes 集群中代表一项已供应存储的资源，其生命周期可以独立于单个 Pod。", "A Kubernetes cluster resource representing provisioned storage, with a lifecycle that can be independent of an individual Pod."], "see": "w-csi", "tag": "generic"},
  "persistent-volume-claim": {"zh": "持久卷声明", "en": "Persistent Volume Claim", "alias": ["PVC", "PVCs", "PersistentVolumeClaim"], "d": ["Kubernetes 工作负载使用存储时提出的申请，描述所需容量和访问模式等要求。", "A Kubernetes request for storage that specifies requirements such as capacity and access modes."], "see": "w-csi", "tag": "generic"},
  "storage-class": {"zh": "Kubernetes 存储类", "en": "Kubernetes Storage Class", "alias": ["StorageClass"], "d": ["定义 Kubernetes 存储类别及其供应插件和参数的资源，可供持久卷声明选择。", "A Kubernetes resource defining a storage class, provisioner, and parameters that persistent volume claims can select."], "see": "w-csi", "tag": "generic"},
  "rbac": {"zh": "基于角色的访问控制", "en": "Role-Based Access Control", "alias": ["RBAC"], "d": ["将权限授予角色，再通过角色向用户、组或服务身份分配权限的访问控制方式。", "An access control model in which permissions are assigned to roles and granted to users, groups, or service identities through those roles."], "see": "f-policy", "tag": "generic"},
  "control-plane": {"zh": "控制平面", "en": "Control Plane", "alias": ["control planes", "控制面"], "d": ["负责系统配置、决策和状态协调的组件。在 Kubernetes 中负责维护集群状态和调度工作负载。", "The components that configure, make decisions for, and coordinate system state. In Kubernetes the control plane maintains cluster state and schedules workloads."], "see": "f-kmgr", "tag": "generic"},
  "device-plugin": {"zh": "设备插件", "en": "Device Plugin", "alias": ["device plugins"], "d": ["将节点上的特殊硬件资源注册到 Kubernetes，使调度器能够分配给容器的组件。", "A component that registers specialized node hardware with Kubernetes so it can be allocated to containers."], "see": "f-sched", "tag": "generic"},
  "gpu-operator": {"zh": "GPU Operator", "en": "NVIDIA GPU Operator", "alias": ["GPU Operator"], "d": ["NVIDIA 用于在 Kubernetes 部署和管理 GPU 驱动、设备插件等软件组件的 Operator。", "An NVIDIA operator for deploying and managing GPU software components such as drivers and device plugins on Kubernetes."], "see": "f-slice", "tag": "nvidia"},
  "network-operator": {"zh": "Network Operator", "en": "NVIDIA Network Operator", "alias": ["Network Operator"], "d": ["NVIDIA 用于在 Kubernetes 部署和管理支持的网络驱动及网络组件的 Operator。", "An NVIDIA operator for deploying and managing supported network drivers and networking components on Kubernetes."], "see": "f-dsx", "tag": "nvidia"},
  "mig": {"zh": "多实例 GPU", "en": "Multi-Instance GPU", "alias": ["MIG", "NVIDIA MIG"], "d": ["NVIDIA 将受支持 GPU 划分为多个实例的功能，为实例分配隔离的计算和显存资源。", "An NVIDIA feature that partitions a supported GPU into instances with isolated compute and GPU memory resources."], "see": "f-slice", "tag": "nvidia"},
  "gpu-time-slicing": {"zh": "GPU 时间片共享", "en": "GPU Time-Slicing", "alias": ["time-slicing", "time slicing", "时间片共享"], "d": ["让多个工作负载交替在同一 GPU 上执行的共享方式。", "A way for multiple workloads to share a GPU by alternating execution on the same device."], "see": "f-slice", "tag": "generic"},
  "bmc": {"zh": "基板管理控制器", "en": "Baseboard Management Controller", "alias": ["BMC", "BMCs"], "d": ["服务器中用于带外监控传感器和管理电源等功能的控制器。", "A server controller used for out-of-band tasks such as monitoring sensors and managing power."], "see": "f-bare", "tag": "generic"},
  "ipmi": {"zh": "智能平台管理接口", "en": "Intelligent Platform Management Interface", "alias": ["IPMI"], "d": ["用于查询传感器、事件和执行电源控制等服务器管理任务的标准接口。", "A standard interface for server management tasks such as reading sensors and events and controlling power."], "see": "v-rack", "tag": "generic"},
  "oob": {"zh": "带外管理", "en": "Out-of-Band Management", "alias": ["out of band management", "OOB management"], "d": ["通过独立于被管系统主业务路径的接口对设备进行监控和管理。", "Monitoring and managing equipment through an interface separate from the managed system’s primary service path."], "see": "f-bare", "tag": "generic"},
  "mpi": {"zh": "消息传递接口", "en": "Message Passing Interface", "alias": ["MPI"], "d": ["并行程序中进程交换消息和执行集合操作的标准接口。", "A standard interface for message exchange and collective operations among processes in parallel programs."], "see": "b-nccltest", "tag": "generic"},
  "all-gather": {"zh": "全收集", "en": "All-Gather", "alias": ["AllGather", "All Gather"], "d": ["把每个参与进程的输入收集起来，并将完整集合交给每个进程的集合操作。", "A collective operation that gathers the input from every participant and returns the complete collection to each participant."], "see": "n-nccl", "tag": "generic"},
  "reduce-scatter": {"zh": "归约分散", "en": "Reduce-Scatter", "alias": ["ReduceScatter", "Reduce Scatter", "规约散播"], "d": ["先归约所有参与进程的输入，再将结果的不同片段分发给各进程的集合操作。", "A collective operation that reduces inputs across participants and distributes different segments of the result among them."], "see": "n-nccl", "tag": "generic"},
  "gpu-kernel": {"zh": "GPU 核函数", "en": "GPU Kernel", "alias": ["CUDA kernel", "CUDA kernels", "GPU kernels", "核函数"], "d": ["由主机发起、在 GPU 上以多线程执行的设备函数。", "A device function launched by a host and executed by multiple threads on a GPU."], "see": "n-cuda", "tag": "generic"},
  "sm": {"zh": "流式多处理器", "en": "Streaming Multiprocessor", "alias": ["streaming multiprocessors", "GPU SM"], "d": ["NVIDIA GPU 中负责调度和执行线程束的计算单元。", "An NVIDIA GPU execution unit that schedules and executes warps."], "see": "n-cuda", "tag": "nvidia"},
  "tensor-core": {"zh": "张量核心", "en": "Tensor Core", "alias": ["Tensor Cores", "张量核"], "d": ["NVIDIA GPU 中用于加速受支持精度下矩阵乘加运算的硬件单元。", "An NVIDIA GPU hardware unit that accelerates matrix multiply-accumulate operations at supported precisions."], "see": "n-hopper", "tag": "nvidia"},
  "nvlink-c2c": {"zh": "NVLink 芯片间互连", "en": "NVLink-C2C", "alias": ["NVLink C2C"], "d": ["NVIDIA 用于连接同一模块内处理器的芯片间互连，可在支持的平台上提供缓存一致性。", "An NVIDIA chip-to-chip interconnect for processors in the same module, with cache coherence on supported platforms."], "see": "n-grace", "tag": "nvidia"},
  "dcgm": {"zh": "数据中心 GPU 管理器", "en": "NVIDIA Data Center GPU Manager", "alias": ["DCGM", "NVIDIA DCGM"], "d": ["NVIDIA 用于监控和管理数据中心 GPU、采集指标和运行诊断的工具集。", "An NVIDIA toolset for monitoring and managing data center GPUs, collecting metrics, and running diagnostics."], "see": "b-dcgm", "tag": "nvidia"},
  "vfs": {"zh": "虚拟文件系统层", "en": "Virtual File System", "alias": ["VFS"], "d": ["操作系统向应用提供统一文件系统接口，并转发到具体文件系统实现的软件层。", "An operating system layer that exposes a common file system interface to applications and dispatches operations to individual file system implementations."], "see": "w-vfs", "tag": "generic"},
  "dpdk": {"zh": "数据平面开发套件", "en": "Data Plane Development Kit", "alias": ["DPDK"], "d": ["用于数据包处理的库和驱动，可让用户态应用管理数据面的收发队列。", "A set of libraries and drivers for packet processing that lets user-space applications manage packet I/O queues."], "see": "w-dpdk", "tag": "generic"},
  "pmd": {"zh": "轮询模式驱动", "en": "Poll Mode Driver", "alias": ["poll mode drivers", "轮询驱动"], "d": ["DPDK 中用于处理设备队列的驱动，应用可主动轮询队列并批量收发数据包。", "A DPDK driver for device queues that allows an application to poll and transfer packets in batches."], "see": "w-dpdk", "tag": "generic"},
  "weka-stateless-client": {"zh": "WEKA 无状态客户端", "en": "WEKA Stateless Client", "alias": ["stateless client", "stateless clients", "无状态客户端"], "d": ["用于挂载远端 WEKA 文件系统且不承担后端存储职责的客户端。", "A client that mounts a remote WEKA file system and does not take on backend storage duties."], "see": "w-dpdk", "tag": "weka"},
  "netq-agent": {"zh": "NetQ 代理", "en": "NetQ Agent", "alias": ["NetQ agents"], "d": ["在受支持网络设备上收集运行状态和事件并将其发送到 NetQ 的软件组件。", "A software component that collects operational state and events on supported network devices and sends them to NetQ."], "see": "n-netq", "tag": "nvidia"},
  "nixl-agent-metadata": {"zh": "NIXL 代理元数据", "en": "NIXL Agent Metadata", "alias": ["Agent metadata"], "d": ["NIXL 传输代理交换的连接与寻址信息，用于定位对端并建立数据传输。", "Connection and addressing information exchanged by NIXL transfer agents to locate peers and set up data transfers."], "see": "n-nixl", "tag": "nvidia"},
  "lustre-dne": {"zh": "Lustre 分布式命名空间", "en": "Distributed Namespace Environment", "alias": ["Lustre DNE", "DNE", "分布式命名空间"], "d": ["Lustre 将元数据分布在多个元数据目标上的机制，支持将目录分布或条带化。", "A Lustre mechanism that distributes metadata across multiple metadata targets and supports placing or striping directories across targets."], "see": "d-dne", "tag": "generic"},
  "lid-gid": {"zh": "全局标识符", "en": "Global Identifier", "alias": ["InfiniBand GID", "GID", "GIDs"], "d": ["在 InfiniBand 架构中标识端口等端点的全局地址，可用于跨子网路由。", "A global address identifying an endpoint such as a port in the InfiniBand architecture, usable for routing across subnets."], "see": "ib", "tag": "generic"},
  "rdma-memory-registration": {"zh": "RDMA 内存注册", "en": "RDMA Memory Registration", "alias": ["memory registration", "registered memory", "内存注册", "已注册内存"], "d": ["向 RDMA 设备登记内存区域及其访问权限，使设备能够按允许的方式访问这些缓冲区。", "Makes a memory region and its permissions known to an RDMA device so it can access those buffers as authorized."], "see": "rdma", "tag": "generic"},
  "zero-copy-staging": {"zh": "主机内存中转", "en": "Host Memory Staging", "alias": ["host staging", "宿主机内存中转"], "d": ["在设备之间传输数据时先把数据放到主机内存，再交给目标设备。", "Moves data between devices by placing it in host memory before passing it to the destination device."], "see": "gds", "tag": "generic"},
  "global-access": {"zh": "全局访问", "en": "Global Access", "alias": ["VAST Global Access"], "d": ["VAST 为选定源路径在对端集群提供访问入口的功能。对端可按需读取并缓存源数据。", "A VAST feature that exposes a selected source path on peer clusters. Peers can fetch and cache source data on demand."], "see": "v-dataspace", "tag": "vast"},
  "loadgen": {"zh": "MLPerf 负载生成器", "en": "MLPerf LoadGen", "alias": ["LoadGen"], "d": ["MLPerf Inference 中按指定场景产生查询并记录完成时间的共用负载生成组件。", "The shared MLPerf Inference component that generates queries according to the selected scenario and records completion times."], "see": "b-mlpi", "tag": "generic"},
  "poisson-arrivals": {"zh": "泊松到达过程", "en": "Poisson Arrivals", "alias": ["Poisson process", "泊松过程"], "d": ["以固定平均速率随机到达的事件序列，独立到达间隔服从指数分布。", "Random event arrivals at a constant average rate, with independent exponentially distributed interarrival times."], "see": "b-mlpi", "tag": "generic"},
  "scale-factor": {"zh": "基准数据规模因子", "en": "Scale Factor", "alias": ["scale factors", "规模因子"], "d": ["TPC-DS 和 TPC-H 中用于指定数据生成规模的参数。", "A TPC-DS and TPC-H parameter specifying the scale of generated data."], "see": "b-tpcds", "tag": "generic"},
  "ce-engine": {"zh": "GPU 拷贝引擎", "en": "GPU Copy Engine", "alias": ["专用拷贝引擎", "dedicated copy engine"], "d": ["执行设备支持的数据复制和传输操作的 GPU 硬件单元。", "A GPU hardware unit that performs supported data copy and transfer operations."], "see": "b-nvbw", "tag": "generic"},
  "sas": {"zh": "串行连接 SCSI", "en": "Serial Attached SCSI", "alias": ["SAS"], "d": ["在存储控制器与驱动器或扩展器之间通过串行链路传输 SCSI 命令的接口。", "An interface that carries SCSI commands over serial links between storage controllers and drives or expanders."], "see": "d-ss9024", "tag": "generic"},
  "namespace-fs": {"zh": "文件系统命名空间", "en": "File System Namespace", "alias": ["filesystem namespace", "文件命名空间"], "d": ["文件与目录可见的命名层级，应用通过其中的路径定位对象。", "The visible naming hierarchy of files and directories, in which applications locate objects by path."], "see": "meta", "tag": "generic"},
  "write-back": {"zh": "回写", "en": "Write-Back", "alias": ["write back", "write-back caching"], "d": ["先在上层缓存保留更新，再在符合策略的时机将状态写到下层的方式。", "A policy that retains updates in an upper cache before writing the state to a lower level."], "see": "f-hicache", "tag": "generic"},
  "write-through": {"zh": "直写", "en": "Write-Through", "alias": ["write through", "write-through caching"], "d": ["在处理当前更新时，同时将状态写到下层的缓存策略。", "A cache policy that writes state to a lower tier as part of processing the current update."], "see": "f-hicache", "tag": "generic"},
  "pcie-root": {"zh": "PCIe 根复合体", "en": "PCIe Root Complex", "alias": [], "d": ["主机与 PCIe 层级之间的接口，连接处理器和内存系统与 PCIe 设备。", "The interface between the host and the PCIe hierarchy, connecting the processor and memory system to PCIe devices."], "see": "nvmeof", "tag": "generic"},
  "kvbm": {"zh": "键值缓存块管理器", "en": "KV Block Manager", "alias": ["KVBM", "Dynamo KV Block Manager"], "d": ["NVIDIA Dynamo 中管理键值缓存块并在受支持的内存和存储层之间进行卸载与回读的组件。", "The NVIDIA Dynamo component that manages KV cache blocks and offloads and retrieves them across supported memory and storage tiers."], "see": "v-kvp", "tag": "nvidia"},
  "nsds": {"zh": "EXAScaler 文件协议网关", "en": "NFS/SMB Data Services", "alias": ["NSDS", "EXAScaler NSDS"], "d": ["DDN EXAScaler 中通过 NFS 或 SMB 向客户端提供后端文件系统访问的组件。", "A DDN EXAScaler component that provides clients access to the backing file system over NFS or SMB."], "see": "d-nas", "tag": "ddn"},
  "hdfs": {"zh": "Hadoop 分布式文件系统", "en": "Hadoop Distributed File System", "alias": ["HDFS"], "d": ["Apache Hadoop 的分布式文件系统。NameNode 管理命名空间与块位置，DataNode 保存和提供文件数据块。", "Apache Hadoop’s distributed file system. NameNodes manage the namespace and block locations, and DataNodes store and serve file blocks."], "see": "meta", "tag": "generic"},
  "opentelemetry": {"zh": "OpenTelemetry", "en": "OpenTelemetry", "alias": [], "d": ["用于生成、收集和导出追踪、指标及日志等遥测数据的一套开放规范和工具。", "An open set of specifications and tools for generating, collecting, and exporting telemetry such as traces, metrics, and logs."], "see": "v-de", "tag": "generic"},
  "iam": {"zh": "身份与访问管理", "en": "Identity and Access Management", "alias": ["IAM"], "d": ["管理用户、服务等主体的身份，并规定其可访问哪些资源和执行哪些操作的机制。", "A set of mechanisms that manage the identities of principals such as users and services and control what resources and actions they can access."], "see": "f-policy", "tag": "generic"}
};
